B.abt=new A.kO("\u062a\u062c\u062f \u0644\u064a\u0644\u0649 \u0628\u0630\u0631\u0629 \u0635\u063a\u064a\u0631\u0629 \u0641\u064a \u0627\u0644\u062d\u062f\u064a\u0642\u0629. \u0647\u0644 \u062a\u0632\u0631\u0639\u0647\u0627 \u0623\u0645 \u062a\u0631\u064a\u0647\u0627 \u0644\u062c\u062f\u062a\u0647\u0627\u061f","Laila finds a tiny seed in the garden. Does she plant it or show it to her grandmother?",B.bpk)
B.abf=new A.li("\u062a\u0633\u0642\u064a\u0647\u0627","Waters it","water")
